from decimal import Decimal, ROUND_HALF_UP
from typing import Any


def _value(row: dict, key: str) -> Any:
    value = row.get(key, "")
    return "" if value is None else value


def _fixed(value: Any, width: int) -> str:
    text = "" if value == "" else str(value)
    return text[:width].ljust(width)


def _zpad_cents(value: Any, width: int) -> str:
    if value == "":
        amount = Decimal(0)
    elif isinstance(value, Decimal):
        amount = value
    else:
        amount = Decimal(str(value))

    cents = (amount * Decimal(100)).quantize(
        Decimal("1"), rounding=ROUND_HALF_UP
    )
    rendered = format(cents, "f")
    return rendered.zfill(width)


